#!/usr/bin/env python3
import hashlib,json,sys,time
from pathlib import Path
import numpy as np,pandas as pd
from sklearn.linear_model import Ridge
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT));OUT=ROOT/'model/REF4-R-SPLIT-PRODUCTION-049A'
from src.entity_context_split import build_split_features,build_split_profile,apply_split_profile,apply_linear_split
def sha(p):
 h=hashlib.sha256()
 with open(p,'rb') as f:
  for b in iter(lambda:f.read(1<<20),b''):h.update(b)
 return h.hexdigest()
def main():
 started=time.time();c=json.loads((OUT/'audit_contract.json').read_text());pre=json.loads((OUT/'preflight_report.json').read_text());assert pre['status']=='AUDIT_VERIFIED' and pre['fail_count']==0;cols=['row_id','season','game_type','control_success','pitcher_id','batter_id','pitcher_hand','batter_hand','balls_before','strikes_before','inning','base_state'];raw=pd.read_csv(ROOT/c['official_train'],usecols=cols);oof={int(y):pd.read_csv(ROOT/p) for y,p in c['base_oof'].items()};shrink=tuple(c['shrinkage_grid']);xs=[];targets=[];weights=[];audits=[]
 for year in (2022,2023,2024):
  rows=oof[year][['row_id']].merge(raw,on='row_id',validate='one_to_one');history=raw.loc[raw.season<year];x=build_split_features(history,rows,shrink);xs.append(x);targets.append(oof[year].target.to_numpy(float)-oof[year].prediction.to_numpy(float));weights.append(np.full(len(x),float(c['season_weights'][str(year)])));audits.append({'season':year,'fit_history_max_season':int(history.season.max()),'rows':len(x),'feature_count':x.shape[1]})
 x=pd.concat(xs,ignore_index=True);target=np.concatenate(targets);w=np.concatenate(weights);mean=x.mean().to_numpy(float);std=x.std().replace(0,1).fillna(1).to_numpy(float);z=np.nan_to_num((x.to_numpy(float)-mean)/std);model=Ridge(alpha=float(c['ridge_alpha']),fit_intercept=False).fit(z,target,sample_weight=w);profile=build_split_profile(raw);profile.to_csv(OUT/'split_profile.csv',index=False,float_format='%.17g');np.savez_compressed(OUT/'split_residual_meta.npz',feature_names=np.asarray(x.columns,dtype='U80'),mean=mean,std=std,coef=model.coef_,alpha=np.float64(c['ridge_alpha']),season_weights=np.asarray([c['season_weights'][str(y)] for y in (2022,2023,2024)],dtype=float),shrinkages=np.asarray(shrink,dtype=float));probe=pd.concat([raw.loc[raw.game_type.eq('R')].tail(int(c['probe_rows_per_regime'])),raw.loc[raw.game_type.eq('F')].tail(int(c['probe_rows_per_regime']))],ignore_index=True);saved_profile=pd.read_csv(OUT/'split_profile.csv',dtype={'entity_value':str,'context_value':str});probe_x=apply_split_profile(probe,saved_profile,shrink);probe['expected_correction']=apply_linear_split(probe_x,OUT/'split_residual_meta.npz');probe.to_csv(OUT/'production_probe.csv',index=False,float_format='%.17g');result={'experiment_id':c['experiment_id'],'candidate_status':'PENDING_AUDIT','oof_fit_rows':len(x),'feature_count':x.shape[1],'feature_names':x.columns.tolist(),'ridge_alpha':c['ridge_alpha'],'season_weights':c['season_weights'],'ridge_coef':model.coef_.tolist(),'standardization_mean':mean.tolist(),'standardization_std':std.tolist(),'fold_audits':audits,'profile_rows':len(profile),'profile_duplicate_keys':int(profile.duplicated(['entity_name','context_name','entity_value','context_value']).sum()),'probe_rows':len(probe),'probe_R_rows':int(probe.game_type.eq('R').sum()),'probe_F_rows':int(probe.game_type.eq('F').sum()),'probe_correction_min':float(probe.expected_correction.min()),'probe_correction_max':float(probe.expected_correction.max()),'test_read':False,'production_assets_created':True,'candidate_bundle_created':False,'zip_created':False,'elapsed_seconds':time.time()-started};(OUT/'result.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n');(OUT/'result.md').write_text(f"# {c['experiment_id']}\n\n- status: `PENDING_AUDIT`\n- OOF fit rows: `{len(x)}`\n- features: `{x.shape[1]}`\n- profile rows: `{len(profile)}`\n- probe rows: `{len(probe)}`\n");paths=[OUT/'audit_contract.json',OUT/'preflight_report.json',OUT/'preflight_report.md',OUT/'result.json',OUT/'result.md',OUT/'split_profile.csv',OUT/'split_residual_meta.npz',OUT/'production_probe.csv',ROOT/c['source_performance_attestation'],ROOT/c['official_train'],ROOT/'01_제약과금지사항.md',ROOT/'src/entity_context_split.py',ROOT/'scripts/preflight_ref4_r_split_production_049a.py',ROOT/'scripts/run_ref4_r_split_production_049a.py',ROOT/'scripts/verify_ref4_r_split_production_049a.py']+[ROOT/p for p in c['base_oof'].values()];arts={str(p.relative_to(ROOT)):{'sha256':sha(p),'size':p.stat().st_size} for p in paths};(OUT/'audit_manifest.json').write_text(json.dumps({'experiment_id':c['experiment_id'],'status':'PENDING_VALIDATION','artifact_count':len(arts),'artifacts':arts,'asset_count':3,'oof_fit_rows':len(x),'feature_count':x.shape[1]},ensure_ascii=False,indent=2)+'\n');print(json.dumps({'oof_fit_rows':len(x),'feature_count':x.shape[1],'profile_rows':len(profile),'probe_rows':len(probe)},indent=2))
if __name__=='__main__':main()
